// Verifies the Stripe signature, rejects events older than 5 minutes and processes each
// checkout session at most once. Returns [] (stops the workflow) for anything invalid.
// Requires on the n8n host: STRIPE_WEBHOOK_SECRET (whsec_...) and NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');

const item = $input.first();
const secret = $env.STRIPE_WEBHOOK_SECRET;
if (!secret) throw new Error('STRIPE_WEBHOOK_SECRET is not set on the n8n host');

const header = item.json.headers['stripe-signature'] || '';
const parts = Object.fromEntries(header.split(',').map((p) => p.split('=')));
const timestamp = Number(parts.t);
const signature = parts.v1;
if (!timestamp || !signature) { console.log('rejected: missing signature header'); return []; }

// Reject events older than 5 minutes (replay protection).
const ageSeconds = Math.floor(Date.now() / 1000) - timestamp;
if (ageSeconds > 300) { console.log(`rejected: event too old (${ageSeconds}s)`); return []; }

// Raw body is required for the HMAC; the Webhook node provides it as binary "data".
const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex');
const a = Buffer.from(expected); const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) { console.log('rejected: bad signature'); return []; }

const event = JSON.parse(rawBody);
if (event.type !== 'checkout.session.completed') { console.log(`ignored: ${event.type}`); return []; }
const session = event.data.object;
if (session.payment_status !== 'paid') { console.log('ignored: not paid'); return []; }

// Idempotency on checkout.session.id, kept in workflow static data (ring buffer of 500 ids).
const store = $getWorkflowStaticData('global');
store.seen = Array.isArray(store.seen) ? store.seen : [];
if (store.seen.includes(session.id)) { console.log('ignored: duplicate session'); return []; }
store.seen.push(session.id);
if (store.seen.length > 500) store.seen.splice(0, store.seen.length - 500);

const email = (session.customer_details && session.customer_details.email) || session.customer_email || '';
const masked = email.replace(/^(.).*(@.*)$/, '$1***$2');
const custom = Array.isArray(session.custom_fields) && session.custom_fields[0] && session.custom_fields[0].text ? session.custom_fields[0].text.value || '' : '';
const amount = (session.amount_total || 0) / 100;
const currency = (session.currency || 'eur').toUpperCase();

// Only the masked address goes to the console log.
console.log(`accepted: ${session.id} ${amount} ${currency} from ${masked}`);

return [{ json: { sessionId: session.id, amount, currency, email, maskedEmail: masked, message: custom, created: new Date(event.created * 1000).toISOString() } }];

